/** Passive reused-v11 recording only. No policy, rollout, candidate or model change. */
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {appendFileSync,statSync} from "node:fs";
import {createInterface} from "node:readline";
import {gzipSync} from "node:zlib";
import {buildChoice} from "./build-choice";
import {fightNative,hash} from "./native-audit";
import {selectBarrelForecastIntent} from "./sources/common/src/simulation/barrel_forecast_intent_research";
import {canWaitOnHourglass,hasActiveTimeDenial} from "./sources/common/src/engine/hourglass";
import {SearchDriver} from "./sources/common/src/simulation/search_driver";
import {captureAITargetMemory} from "./sources/common/src/ai/ai";
import {captureDeterministicRandomState} from "./sources/common/src/utils/lib";
import {permuteRankedDraftSeed} from "./sources/common/src/simulation/ranked_draft_eval";
import {V08_A19_PROFILE_SCHEMA} from "./sources/common/src/ai/versions/v0_8_a19_profile";
import {environment} from "./profiles";
const [output,labelOutput,stateOutput,mode]=process.argv.slice(2),g=globalThis as any;
assert(["baseline","observe"].includes(mode));assert.equal(V08_A19_PROFILE_SCHEMA,"hoc.v0_8_a19_production_profile.v11");
assert.equal(environment.SEARCH_ROLLOUTS,"2");assert.equal(environment.SEARCH_HORIZON,"64");
let collecting=false,fault:string|undefined,turns=0,pending:any[]=[],labels:any[]=[],rootRecords:any[]=[];
let activeRoot:any,activeQuery:any;
let live:any,frames:any[]=[],committedTurns:any[]=[],unitRefs:WeakMap<object,number>,nextUnitRef=0;
let turnHash:ReturnType<typeof createHash>,eventHash:ReturnType<typeof createHash>;
const proto=SearchDriver.prototype as any,choose=proto.chooseDecision,shortlist=proto.shortlistCandidates,score=proto.scoreCandidates,rollout=proto.rollout;
const clone=(x:any)=>structuredClone(x);
const candidates=(xs:any[])=>xs.map(x=>clone(x));
const observing=()=>collecting&&mode==="observe";
function fail(error:unknown){fault=String(error);throw error;}
proto.chooseDecision=function(unit:any,version:any,incumbent:any,context:any){
    if(collecting){
        assert.equal(this.barrelForecastMixture,false);assert.equal(this.liveCertifiedBounds,false);
        assert.equal(this.scoredDecisionObserver,undefined);assert.equal(this.passiveProductiveProbeObserver,undefined);
    }
    if(!observing()||!pending.some(p=>p.actualTurn===turns&&p.unitId===unit.getId()))return choose.call(this,unit,version,incumbent,context);
    const previous=activeRoot;
    const record={actualTurn:turns,unitId:unit.getId(),version,rawIncumbent:clone(incumbent),shortlists:[] as any[],queries:[] as any[],innerChosen:undefined as any};
    activeRoot=record;rootRecords.push(record);
    try{const selected=choose.call(this,unit,version,incumbent,context);record.innerChosen=clone(selected);return selected;}
    catch(error){return fail(error);}
    finally{activeRoot=previous;}
};
proto.shortlistCandidates=function(unit:any,xs:any[],...args:any[]){
    if(!observing()||!activeRoot)return shortlist.call(this,unit,xs,...args);
    try{
        const input=candidates(xs),selected=shortlist.call(this,unit,xs,...args);
        activeRoot.shortlists.push({input,output:candidates(selected),unitId:unit.getId()});return selected;
    }catch(error){return fail(error);}
};
proto.scoreCandidates=function(unit:any,xs:any[],...args:any[]){
    if(!observing()||!activeRoot)return score.call(this,unit,xs,...args);
    const prior=activeQuery;
    const q={unitId:unit.getId(),mode:args[1],rollouts:args[2]??this.rollouts,turnHorizon:args[4]??this.horizon,
        // Seeds are replay metadata only; projected values and action results are labels/diagnostics.
        seedBase:args[0],candidates:candidates(xs),samples:[] as any[],scores:[] as any[],indices:new Map(xs.map((c,i)=>[c,i]))};
    activeQuery=q;
    try{
        const result=score.call(this,unit,xs,...args);
        q.scores=result.map((v:number)=>({value:Number.isFinite(v)?v:null,tag:Number.isFinite(v)?"finite":String(v)}));
        const {indices,...detached}=q;activeRoot.queries.push(detached);return result;
    }catch(error){return fail(error);}
    finally{activeQuery=prior;}
};
proto.rollout=function(unit:any,candidate:any,...args:any[]){
    if(!observing()||!activeRoot||!activeQuery)return rollout.call(this,unit,candidate,...args);
    assert(activeQuery.indices.has(candidate));
    const query=activeQuery,index=query.indices.get(candidate),engine=this.deps.engine;
    const descriptor=Object.getOwnPropertyDescriptor(engine,"apply"),apply=engine.apply,attempts:any[]=[];
    let nextRootAction=0,value:number|undefined;
    Object.defineProperty(engine,"apply",{configurable:true,writable:true,value:function(action:any){
        const rootAction=nextRootAction<candidate.actions.length&&action===candidate.actions[nextRootAction];
        const data=rootAction?clone(action):undefined;if(rootAction)nextRootAction++;
        const result=apply.call(this,action);
        if(rootAction)attempts.push({action:data,completed:result.completed,rejectionReason:result.rejectionReason});
        return result;
    }});
    try{value=rollout.call(this,unit,candidate,...args);return value;}
    catch(error){return fail(error);}
    finally{
        if(descriptor)Object.defineProperty(engine,"apply",descriptor);else Reflect.deleteProperty(engine,"apply");
        query.samples.push({candidateIndex:index,sampleIndex:args[1],mode:args[2],attempts,
            score:value!==undefined&&Number.isFinite(value)?value:null,
            scoreTag:value===undefined?"thrown":Number.isFinite(value)?"finite":String(value)});
    }
};
function publicUnit(u:any,fp:any,all:any){
    return {id:u.getId(),name:u.getName(),team:u.getTeam(),cells:clone(u.getCells()),hp:u.getCumulativeHp(),alive:u.getAmountAlive(),
        maxHp:u.getMaxHp(),exp:u.getExp(),steps:u.getSteps(),initiative:u.getInitiative(),armor:u.getArmor(),rangeArmor:u.getRangeArmor(),
        shots:u.getRangeShots(),fly:u.canFly(),dead:u.isDead(),attackSelection:u.getAttackTypeSelection(),properties:clone(u.getUnitProperties()),
        spells:u.getSpells().map((s:any)=>({name:s.getName(),remaining:s.getAmount(),properties:s.getSpellProperties()})),
        turnLegality:{hasMoved:u.hasMovedThisTurn(),isOnHourglass:u.isOnHourglass(),hourglassIncludes:fp.hourglassIncludes(u.getId()),
            alreadyMadeTurn:fp.hasAlreadyMadeTurn(u.getId()),alreadyHourglass:fp.hasAlreadyHourglass(u.getId()),
            activeTimeDenial:u.hasAbilityActive("Time Denial"),
            hasUnactedTeammate:fp.hasUnactedTeammate(u.getTeam(),u.getId(),all),canWait:canWaitOnHourglass(u,fp,all)}};
}
g.__barrelLegalRootObservation=(unit:any,context:any,before:any[],cleanup:any[])=>{
    if(!observing()||context.decisionOrigin!=="root")return cleanup;
    try{
        if(selectBarrelForecastIntent(unit,{...context,decisionOrigin:"rollout"},before,cleanup)===cleanup)return cleanup;
        const all=context.unitsHolder.getAllUnits(),fp=context.fightProperties;
        pending.push({actualTurn:turns,unitId:unit.getId(),actor:unit.getName(),team:unit.getTeam(),lap:fp.getCurrentLap(),
            before:clone(before),cleanup:clone(cleanup),publicState:{gridType:context.grid.getGridType(),matrix:clone(context.matrix),
                gridGeometry:{gridSize:context.grid.getSettings().getGridSize(),cellSize:context.grid.getSettings().getCellSize(),maxX:context.grid.getSettings().getMaxX()},
                units:[...all.values()].map((u:any)=>publicUnit(u,fp,all)),activeTimeDenial:hasActiveTimeDenial(all.values()),
                barrels:clone(context.grid.getArtifactBarrels()),terrain:clone(context.grid.getScatteredMountainsStanding()),upNext:[...fp.getUpNextQueueIterable()]}});
    }catch(error){return fail(error);}
    return cleanup;
};
function capture(turn:any|null){
    const references=[...live.unitsHolder.getAllUnits()].map(([id,object]:any)=>{
        let token=unitRefs.get(object);if(token===undefined){token=nextUnitRef++;unitRefs.set(object,token);}return[id,token,object.constructor.name];
    });
    const random=captureDeterministicRandomState();
    frames.push({frame:frames.length,unitReferenceTokens:references,targetMemorySha256:hash([...captureAITargetMemory(live.unitsHolder)]),
        uuidSequence:random.uuidSequence,liveRandomDrawCount:g.__auditRng.count,liveRandomPrefixSha256:g.__auditRng.hash.copy().digest("hex"),
        actualTurnPrefixSha256:turnHash.copy().digest("hex"),eventPrefixSha256:eventHash.copy().digest("hex"),
        rawAndChosenShareArray:turn?turn.rawIncumbent===turn.chosenDecision:null});
}
g.__legalCommittedEvent=(r:any)=>eventHash.update(JSON.stringify(r));
g.__rushBeforeFight=(context:any)=>{live=context;capture(null);};
g.__rushTurn=(r:any)=>{
    turnHash.update(JSON.stringify(r));capture(r);
    committedTurns.push({unitId:r.unitId,creatureName:r.creatureName,rawIncumbent:r.rawIncumbent,chosenDecision:r.chosenDecision});
    if(observing())for(const observation of pending){
        assert.equal(observation.actualTurn,turns);assert.equal(observation.unitId,r.unitId);
        const actor=observation.publicState.units.find((u:any)=>u.id===r.unitId);assert(actor);
        for(const a of r.strategyActions)if(a.action.type==="wait_turn"&&a.completed)assert(actor.turnLegality.canWait,"Successful actual wait must be legal at the recorded root");
        const roots=rootRecords.filter(x=>x.actualTurn===turns&&x.unitId===r.unitId);
        labels.push({...observation,ordinal:labels.length,rootCallOrdinal:labels.filter(o=>o.actualTurn===turns).length,
            strategyVersion:r.strategyVersion,rootCatalogStatus:roots.length?"searched-root":"native-only-or-search-bypass",
            rootRecords:clone(roots),actualRawIncumbent:clone(r.rawIncumbent),chosenDecision:clone(r.chosenDecision),
            strategyActions:clone(r.strategyActions),recovery:clone(r.recovery),rawAndChosenShareArray:r.rawIncumbent===r.chosenDecision});
    }
    pending=[];rootRecords=[];turns++;
};
g.__mixtureDecisionCompleted=(o:any)=>assert.equal(o.context.a19BarrelIntentForecast,undefined);
function append(path:string,row:any){
    const raw=gzipSync(JSON.stringify(row)+"\n",{level:1});let size=0;try{size=statSync(path).size;}catch{}
    assert(size+raw.length<=128*1024*1024,"Fixed actor output ceiling; never truncate or retry");appendFileSync(path,raw);
}
for await(const line of createInterface({input:process.stdin})){
    const {job,registrationSha256}=JSON.parse(line);assert.equal(job.mode,mode);
    collecting=false;fault=undefined;turns=0;pending=[];labels=[];rootRecords=[];activeRoot=undefined;activeQuery=undefined;
    g.__mode="stock";g.__mixtureLiveMode=false;
    const team=(job.game<2)===(job.game%2===0)?2:1,combatSeed=permuteRankedDraftSeed(job.seed+6+Number(job.game>=2));
    const built=buildChoice(job,"current","current",team);
    assert.equal(hash(built.drafted.config),job.draftConfigSha256[Number(job.game>=2)]);
    const inputSha256=hash({config:built.opening.config,teams:built.opening.teams,terrain:built.opening.terrain,combatSeed});
    assert.equal(inputSha256,job.reference.inputSha256);
    frames=[];committedTurns=[];unitRefs=new WeakMap();nextUnitRef=0;turnHash=createHash("sha256");eventHash=createHash("sha256");
    collecting=true;let fought:ReturnType<typeof fightNative>;
    try{fought=fightNative(clone(built.opening),combatSeed);}finally{collecting=false;}
    const score=fought.result.winner==="draw"?.5:Number(fought.result.winner===(team===2?"green":"red"));
    assert(["preflight","train","validation","test"].includes(job.fold));
    const labelPayload={jobId:job.jobId,mode,familyId:job.familyId,fold:job.fold,labels};
    append(labelOutput.replace(/\.jsonl\.gz$/,`.${job.fold}.jsonl.gz`),labelPayload);
    append(output,{...job,registrationSha256,inputSha256,traceSha256:fought.traceSha256,score,winner:fought.result.winner,
        actualTurns:turns,frames,frameDigest:hash(frames),labels:labels.length,labelsDigest:hash(labels),labelPayloadSha256:hash(labelPayload),actualTurnsSha256:hash(committedTurns),quality:fought.quality,
        observationFault:fault??null,pendingUncommitted:clone(pending),rootRecordsUncommitted:clone(rootRecords),
        additionalRolloutsRequested:0,sourceProfile:"frozen-v11-reused-stock-teacher",defaultChanged:false,modelFitted:false});
    // Emit every completed observation before a failed original control stops the single attempt.
    assert(!fault,`Observation error swallowed: ${fault}`);assert.equal(pending.length,0);assert.equal(rootRecords.length,0);
    assert.equal(fought.result.endReason,"elimination");
    assert.equal(fought.traceSha256,job.reference.traceSha256);assert.equal(score,job.reference.score);
    assert.equal(fought.result.winner,job.reference.winner);
    if(job.reference.actualTurns!==undefined)assert.equal(turns,job.reference.actualTurns);
    if(job.reference.actualTurnsSha256)assert.equal(hash(committedTurns),job.reference.actualTurnsSha256);
    if(job.reference.labelsDigest)assert.equal(hash(labels),job.reference.labelsDigest);
    if(job.reference.lightFrameDigest)assert.equal(hash(frames),job.reference.lightFrameDigest);
    const normalizedQuality=JSON.parse(JSON.stringify(fought.quality));
    if(job.reference.neural)assert.deepEqual(normalizedQuality.neural,job.reference.neural);
    if(job.reference.logicalWork)assert.deepEqual(normalizedQuality.work.map((w:any)=>Object.fromEntries(Object.entries(w).filter(([k])=>k!=="msTotal"))),job.reference.logicalWork);
    if(job.reference.searchUses)assert.deepEqual(normalizedQuality.searchUses,job.reference.searchUses);
    for(const n of fought.quality.neural)for(const k of["modelErrors","missingStart","deadlineAbstentions","inferenceOverruns"])assert.equal(n[k],0);
    for(const w of fought.quality.work)for(const k of["deadlineFallbacks","degradedDecisions","circuitSkipped","circuitWaitArbitrations"])assert.equal(w[k]??0,0);
    console.log(JSON.stringify({verified:true,jobId:job.jobId,rows:1,labels:labels.length}));
}

"""One fixed acquisition phase on one host. Never reassigns, retries or extends a case."""
from pathlib import Path
import concurrent.futures,hashlib,json,os,queue,shutil,subprocess,sys,threading,time
p=Path(__file__).resolve().parent;stage,host=sys.argv[1:3]
assert stage in ['preflight','collection','cold']and host in ['local','puffalo']
raw=(p/'registration.json').read_bytes();reg=json.loads(raw);seal=hashlib.sha256(raw).hexdigest()
for f in reg['files']:assert hashlib.sha256((p/f['path']).read_bytes()).hexdigest()==f['sha256'],f['path']
assert subprocess.check_output(['bun','--version'],text=True).strip()=='1.4.4'
deadline=reg['deadlines'][stage];assert time.time()<deadline
if stage!='preflight':
 gate=json.loads((p/('preflight-all-hosts.json'if stage=='collection'else'collection-all-hosts.json')).read_text())
 assert gate['passed']and gate['registrationSha256']==seal
cases=json.loads((p/('preflight-cases.json'if stage=='preflight'else f'cases-{host}.json'if stage=='collection'else'cold-cases.json')).read_text())
assert len(cases)==(14 if stage=='preflight'else reg['hostCases'][host]if stage=='collection'else 36)
if stage=='cold':
 refs=json.loads((p/'cold-reference-index.json').read_text());assert refs['registrationSha256']==seal
 for c in cases:
  ref=refs['cases'][c['caseId']];c['reference'].update({'labelsDigest':ref['labelsDigest'],'lightFrameDigest':ref['frameDigest']})
workers=reg['workers'][stage][host];out=p/f'{stage}-{host}';out.mkdir()
minimum=reg['minimumFreeBytes'][host];assert shutil.disk_usage(p).free>=minimum
q=queue.Queue()
for c in cases:q.put(c)
lock=threading.Lock();stop=threading.Event();processes=[];started=time.monotonic()
state={'complete':False,'stage':stage,'host':host,'fights':0,'expectedFights':len(cases),'observations':0,
 'errors':[],'controllerPid':os.getpid(),'registrationSha256':seal,'absoluteDeadlineEpoch':deadline}
def save():
 with lock:
  value={**state,'elapsedSeconds':round(time.monotonic()-started,3),'liveWorkerPids':[x.pid for x in processes if x.poll()is None]}
  f=out/'status.tmp';f.write_text(json.dumps(value)+'\n');f.replace(out/'status.json')
def halt(reason):
 with lock:
  if stop.is_set():return
  stop.set();state['errors'].append(reason)
 for proc in list(processes):
  if proc.poll()is None:proc.terminate()
timer=threading.Timer(deadline-time.time(),lambda:halt('Fixed phase cutoff reached; no retry or extension'))
timer.daemon=True;timer.start()
def lane(index):
 log=(out/f'worker-{index}.log').open('x');proc=None;error=None
 try:
  proc=subprocess.Popen(['nice','-n','19','bun','--preload',str(p/'alias.ts'),str(p/'actor.ts'),
   str(out/f'worker-{index}.jsonl.gz'),str(out/f'worker-{index}-labels.jsonl.gz'),str(out/f'worker-{index}-unused-states.jsonl.gz'),'observe'],
   cwd=p,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log,text=True,bufsize=1,env={**os.environ,'HOC_A19_CONTEXT_POLICY':'on'})
  with lock:processes.append(proc)
  while not stop.is_set():
   try:base=q.get_nowait()
   except queue.Empty:break
   assert time.time()<deadline
   job={**base,'stage':stage,'host':host,'mode':'observe','jobId':f"{stage}/{base['caseId']}"}
   proc.stdin.write(json.dumps({'job':job,'registrationSha256':seal})+'\n');proc.stdin.flush()
   while True:
    line=proc.stdout.readline()
    if not line:raise RuntimeError(f'{stage}/{host} worker{index} exited at '+job['jobId'])
    try:ack=json.loads(line)
    except json.JSONDecodeError:log.write(line);continue
    if isinstance(ack,dict)and ack.get('verified'):break
    log.write(line)
   assert ack['jobId']==job['jobId']and ack['rows']==1
   with lock:state['fights']+=1;state['observations']+=ack['labels']
 except BaseException as exc:error=exc;halt(repr(exc));raise
 finally:
  if proc:
   if proc.poll()is None:
    try:proc.stdin.close()
    except BrokenPipeError:pass
   if stop.is_set()and proc.poll()is None:proc.terminate()
   code=proc.wait()
   if error is None and not stop.is_set():assert code==0
  log.close()
try:
 save()
 with concurrent.futures.ThreadPoolExecutor(max_workers=workers)as pool:
  futures=[pool.submit(lane,i)for i in range(workers)]
  while not all(f.done()for f in futures):
   for f in futures:
    if f.done()and f.exception()is not None:halt(repr(f.exception()))
   if not stop.is_set()and(shutil.disk_usage(p).free<minimum or sum(f.stat().st_size for f in out.glob('*.gz'))>reg['maximumStageBytes']):halt('Fixed disk floor or phase byte ceiling reached; preserve all records')
   save();time.sleep(3)
  for f in futures:f.result()
 assert not stop.is_set()and state['fights']==len(cases)
 state['complete']=True
except BaseException as error:halt(repr(error));raise
finally:timer.cancel();save()

"""One host advances only through source-bound verification markers. No fitter or policy activation."""
from pathlib import Path
import datetime,hashlib,json,os,subprocess,sys,time
p=Path(__file__).resolve().parent;host=sys.argv[1];assert host in ['local','puffalo']
raw=(p/'registration.json').read_bytes();reg=json.loads(raw);seal=hashlib.sha256(raw).hexdigest()
state={'complete':False,'host':host,'stage':'preflight','supervisorPid':os.getpid(),'registrationSha256':seal,'errors':[],
 'noAutomaticRetryReassignmentFittingOrDeployment':True}
def save():
 state['at']=datetime.datetime.now(datetime.timezone.utc).isoformat();f=p/f'supervisor-{host}.tmp';f.write_text(json.dumps(state,indent=2)+'\n');f.replace(p/f'supervisor-{host}.json')
def wait_gate(name,next_stage):
 state['stage']='waiting-for-'+name;save()
 while True:
  assert time.time()<reg['deadlines'][next_stage],'Fixed next-phase cutoff reached; no extension'
  f=p/(name+'.json')
  if f.exists():
   gate=json.loads(f.read_text());assert gate['passed']and gate['registrationSha256']==seal;return
  time.sleep(20)
save()
try:
 for stage in ['preflight','collection','cold']:
  if stage=='collection':wait_gate('preflight-all-hosts',stage)
  if stage=='cold':wait_gate('collection-all-hosts',stage)
  state['stage']=stage;save()
  with(p/f'{stage}-{host}-controller.log').open('x')as log:
   subprocess.run(['python3',str(p/'run.py'),stage,host],cwd=p,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,check=True)
  result=json.loads((p/f'{stage}-{host}/status.json').read_text());assert result['complete']and not result['errors']and not result['liveWorkerPids']
 state.update({'complete':True,'stage':'complete-awaiting-independent-data-validation'})
except BaseException as error:state['errors'].append(repr(error));state['stage']='failed-preserve-all-records';raise
finally:save()

/** Independent integrity only. Test labels may be checked but never summarized for model selection. */
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {createReadStream,readFileSync,readdirSync,writeFileSync} from "node:fs";
import {createInterface} from "node:readline";
import {createGunzip} from "node:zlib";
const p=import.meta.dir,phase=process.argv[2];assert(["preflight","complete"].includes(phase));
const read=(f:string)=>JSON.parse(readFileSync(`${p}/${f}`,"utf8"));
const sha=(b:Buffer)=>createHash("sha256").update(b).digest("hex"),hash=(v:unknown)=>createHash("sha256").update(JSON.stringify(v)).digest("hex");
const reg=read("registration.json"),seal=sha(readFileSync(`${p}/registration.json`));
for(const f of reg.files)assert.equal(sha(readFileSync(`${p}/${f.path}`)),f.sha256,f.path);
const original=read("cases-all.json"),preflight=read("preflight-cases.json"),cold=read("cold-cases.json");
const byCase=new Map<string,any>(original.map((j:any)=>[j.caseId,j]));assert.equal(byCase.size,6048);
const records=new Map<string,any>(),inventory:any[]=[],folds=new Map<string,string>();let totalObservations=0;
const logical=(xs:any[])=>xs.map(x=>Object.fromEntries(Object.entries(x).filter(([k])=>k!=="msTotal")));
async function* lines(file:string){for await(const line of createInterface({input:createReadStream(file).pipe(createGunzip()),crlfDelay:Infinity}))yield JSON.parse(line);}
for(const stage of phase==="preflight"?["preflight"]:["preflight","collection","cold"]){
 for(const host of["local","puffalo"]){
  const stem=`${stage}-${host}`,dir=`${p}/${stem}`,status=read(`${stem}/status.json`);
  const jobs=stage==="preflight"?preflight:stage==="cold"?cold:original.filter((j:any)=>j.assignedHost===host);
  const expected=new Map<string,any>(jobs.map((j:any)=>[j.caseId,j]));
  assert(status.complete&&!status.errors.length&&!status.liveWorkerPids.length);assert.equal(status.registrationSha256,seal);assert.equal(status.fights,jobs.length);
  const controls=new Map<string,any>(),payloads=new Set<string>();let observations=0;
  const files=readdirSync(dir).filter(f=>f.endsWith(".jsonl.gz")).sort();
  for(const file of files){const raw=readFileSync(`${dir}/${file}`);inventory.push({path:`${stem}/${file}`,bytes:raw.length,sha256:sha(raw)});}
  for(const file of files.filter(f=>/^worker-\d+\.jsonl\.gz$/.test(f)))for await(const r of lines(`${dir}/${file}`)){
   const j=expected.get(r.caseId);assert(j);assert(!controls.has(r.caseId));controls.set(r.caseId,r);
   assert.equal(r.registrationSha256,seal);assert.equal(r.stage,stage);assert.equal(r.host,host);assert.equal(r.mode,"observe");assert.equal(r.fold,j.fold);assert.equal(r.familyId,j.familyId);
   assert.equal(r.jobId,`${stage}/${r.caseId}`);assert.equal(r.inputSha256,j.reference.inputSha256);assert.equal(r.traceSha256,j.reference.traceSha256);assert.equal(r.score,j.reference.score);assert.equal(r.winner,j.reference.winner);
